import{_ as a,C as s,o as n,c as o,ah as r,E as i,j as h}from"./chunks/framework.Be4_4mPW.js";const w=JSON.parse('{"title":"Phase 0: foundations in place","description":"","frontmatter":{"title":"Phase 0: foundations in place","date":"2026-10-24T00:00:00.000Z","phase":0,"status":"gate"},"headers":[],"relativePath":"blog/phase-0-foundations.md","filePath":"blog/phase-0-foundations.md"}'),d={name:"blog/phase-0-foundations.md"};function l(c,e,p,u,m,f){const t=s("Mermaid");return n(),o("div",null,[e[0]||(e[0]=r('<h1 id="phase-0-foundations-in-place" tabindex="-1">Phase 0: foundations in place <a class="header-anchor" href="#phase-0-foundations-in-place" aria-label="Permalink to &quot;Phase 0: foundations in place&quot;">​</a></h1><p>Phase 0 is done. Nothing a player would see exists yet. What exists is everything the next three phases build on: the repo and its checks, the schemas for every document, this site with a live preview of every pull request, and answers to the open questions that could have changed the design.</p><h2 id="what-was-built" tabindex="-1">What was built <a class="header-anchor" href="#what-was-built" aria-label="Permalink to &quot;What was built&quot;">​</a></h2><ul><li><strong>The repo and its checks.</strong> A TypeScript monorepo in strict mode. Every pull request runs lint, unit tests, a production build and browser tests. CI also checks that every requirement in the specification belongs to a work package, and that every diagram parses.</li><li><strong>Schemas for every document.</strong> Each document the game stores has a runtime schema, and the TypeScript types are inferred from it. The <a href="./../data-dictionary.html">data dictionary</a> is generated from the same schemas, as the earlier post <a href="./schemas-and-data-dictionary.html">Schemas first, and a dictionary that writes itself</a> describes.</li><li><strong>This site, and a preview of every pull request.</strong> Each pull request gets its own copy of this site with the app built in, on the mock backend. A bot comment on the pull request links to it and shows screenshots of anything that changed, beside the same page on <code>main</code>. The <a href="./../prs.html">PR index</a> lists every preview.</li></ul><h2 id="what-was-decided" tabindex="-1">What was decided <a class="header-anchor" href="#what-was-decided" aria-label="Permalink to &quot;What was decided&quot;">​</a></h2><p>Three choices were open at the start, and each was settled by building the same small thing two ways:</p><table tabindex="0"><thead><tr><th>Question</th><th>Choice</th><th>Why</th></tr></thead><tbody><tr><td>Dockable layout library</td><td>FlexLayout</td><td>Smaller, fully open-source, and its layout model can be tested without a browser. dockview is the fallback</td></tr><tr><td>XMPP client library</td><td>StanzaJS</td><td>Typed support for nearly everything we need, and it passed every live test against the chosen server</td></tr><tr><td>Site generator</td><td>VitePress</td><td>Builds offline, renders diagrams from a bundled library, and can embed the app</td></tr></tbody></table><p>Neither choice is free. Each library has a single maintainer, and FlexLayout is not yet at version 1.0. Both sit behind interfaces of our own, so either can be replaced without touching the rest of the app.</p><p>A round of tests against the chosen XMPP server also settled how the admin tooling has to work in places where the standards leave room. Those findings changed one requirement and added work to Phase 2, and the specification now records them.</p><h2 id="what-s-next" tabindex="-1">What&#39;s next <a class="header-anchor" href="#what-s-next" aria-label="Permalink to &quot;What&#39;s next&quot;">​</a></h2><p>Phase 1 builds the contracts and the transports:</p>',11)),i(t,{code:"flowchart%20LR%0A%20%20%20%20interface%5B%22Transport%20interface%22%5D%20--%3E%20contract%5B%22Contract%20tests%22%5D%0A%20%20%20%20interface%20--%3E%20real%5B%22Real%20XMPP%20transport%22%5D%0A%20%20%20%20interface%20--%3E%20mock%5B%22In-browser%20mock%20server%22%5D%0A%20%20%20%20interface%20--%3E%20domain%5B%22Domain%20layer%20and%20hooks%22%5D%0A%20%20%20%20contract%20-.%20%22judges%20both%22%20.-%3E%20real%20%26%20mock%0A"}),e[1]||(e[1]=h("p",null,"One interface sits between the app and the backend. Two implementations sit behind it: the real XMPP server, and a mock that runs in the browser for demos. One set of contract tests runs against both, so the mock behaves like the real server or the build fails.",-1))])}const y=a(d,[["render",l]]);export{w as __pageData,y as default};
